def glom_cli(target, spec, indent, debug, inspect, scalar):
    if inspect:
        spec = Inspect(spec)
    try:
        result = glom.glom(target, spec)
    except GlomError as e:
        raise CommandLineError(str(e))

    if scalar:
        sys.stdout.write(str(result))
        return 0

    if indent == 0:
        indent = None

    try:
        output = json.dumps(result, indent=indent)
    except TypeError:
        output = repr(result)

    print(output)
    return 0
```

